using System;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Windows.Forms;
namespace AshkanFitPro {
 public partial class ProgressAnalyticsForm : Form {
  readonly Repository repo; readonly bool fa;
  public ProgressAnalyticsForm(Repository repository,bool persian){repo=repository;fa=persian;InitializeComponent();Text=fa?"تحلیل پیشرفت ورزشی":"Body progress analytics";memberLabel.Text=fa?"عضو":"Member";exportButton.Text=fa?"خروجی CSV":"Export CSV";summaryLabel.Text="";
   foreach(var m in repo.Data.Members.OrderBy(x=>x.Name))memberBox.Items.Add(new MemberChoice(m));
   memberBox.SelectedIndexChanged+=(s,e)=>RefreshView();exportButton.Click+=(s,e)=>ExportCsv();chartPanel.Paint+=(s,e)=>DrawChart(e.Graphics,chartPanel.ClientRectangle);
   chartPanel.Resize+=(s,e)=>chartPanel.Invalidate();if(memberBox.Items.Count>0)memberBox.SelectedIndex=0;else summaryLabel.Text=fa?"عضوی ثبت نشده است":"No members yet";
  }
  sealed class MemberChoice {public Member Value;public MemberChoice(Member m){Value=m;}public override string ToString(){return Value.Name;}}
  BodyProgress[] Records(){var choice=memberBox.SelectedItem as MemberChoice;return choice==null?new BodyProgress[0]:repo.Data.BodyProgressRecords.Where(r=>r.MemberId==choice.Value.Id).OrderBy(r=>r.RecordedAt).ThenBy(r=>r.Id).ToArray();}
  void RefreshView(){var items=Records();recordsGrid.Rows.Clear();foreach(var r in items.Reverse())recordsGrid.Rows.Add(r.RecordedAt.ToString("yyyy-MM-dd"),r.WeightKg,r.Bmi,r.WaistCm,r.BodyFatPercent,r.Goal);if(items.Length==0)summaryLabel.Text=fa?"هنوز اندازه‌گیری ثبت نشده است":"No measurements yet";else {var first=items[0];var last=items[items.Length-1];var delta=last.WeightKg-first.WeightKg;summaryLabel.Text=(fa?"تعداد: ":"Records: ")+items.Length+"   |   "+(fa?"آخرین BMI: ":"Latest BMI: ")+last.Bmi.ToString("0.0")+"   |   "+(fa?"تغییر وزن: ":"Weight change: ")+delta.ToString("+0.0;-0.0;0.0")+" kg"+"   |   "+(fa?"تغییر BMI: ":"BMI change: ")+(last.Bmi-first.Bmi).ToString("+0.0;-0.0;0.0")+"   |   "+(fa?"تغییر دور کمر: ":"Waist change: ")+(last.WaistCm-first.WaistCm).ToString("+0.0;-0.0;0.0")+" cm"+"   |   "+(fa?"تغییر چربی: ":"Body fat change: ")+(last.BodyFatPercent-first.BodyFatPercent).ToString("+0.0;-0.0;0.0")+" %";}chartPanel.Invalidate();}
  void DrawChart(Graphics g,Rectangle bounds){g.Clear(Color.FromArgb(19,33,49));var items=Records();if(items.Length==0){using(var b=new SolidBrush(Color.Gainsboro))g.DrawString(fa?"داده‌ای برای نمایش وجود ندارد":"No data to chart",Font,b,new PointF(20,30));return;}var area=new Rectangle(60,25,Math.Max(1,bounds.Width-90),Math.Max(1,bounds.Height-70));if(area.Width<20||area.Height<20)return;var weights=items.Select(x=>(double)x.WeightKg).ToArray();var min=weights.Min();var max=weights.Max();var pad=Math.Max(1,(max-min)*.15);min-=pad;max+=pad;using(var axis=new Pen(Color.FromArgb(100,130,145)))using(var line=new Pen(Color.FromArgb(35,220,190),3))using(var dot=new SolidBrush(Color.FromArgb(35,220,190)))using(var ink=new SolidBrush(Color.Gainsboro)){g.DrawLine(axis,area.Left,area.Bottom,area.Right,area.Bottom);g.DrawLine(axis,area.Left,area.Top,area.Left,area.Bottom);for(int i=0;i<items.Length;i++){float x=items.Length==1?area.Left+area.Width/2f:area.Left+i*area.Width/(float)(items.Length-1);float y=area.Bottom-(float)((weights[i]-min)/(max-min)*area.Height);if(i>0){float px=items.Length==1?x:area.Left+(i-1)*area.Width/(float)(items.Length-1);float py=area.Bottom-(float)((weights[i-1]-min)/(max-min)*area.Height);g.DrawLine(line,px,py,x,y);}g.FillEllipse(dot,x-4,y-4,8,8);}g.DrawString(max.ToString("0.0")+" kg",Font,ink,2,area.Top);g.DrawString(min.ToString("0.0")+" kg",Font,ink,2,area.Bottom-15);g.DrawString(items[0].RecordedAt.ToString("yyyy-MM-dd"),Font,ink,area.Left,area.Bottom+8);if(items.Length>1)g.DrawString(items[items.Length-1].RecordedAt.ToString("yyyy-MM-dd"),Font,ink,Math.Max(area.Left,area.Right-90),area.Bottom+8);}}
  static string Csv(string s){return "\""+(s??"").Replace("\"","\"\"")+"\"";}
  void ExportCsv(){var records=Records();if(records.Length==0){MessageBox.Show(fa?"رکوردی برای خروجی وجود ندارد":"No records to export");return;}using(var dialog=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="ashkanfit-progress.csv"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;var rows=new System.Collections.Generic.List<string>{"Date,WeightKg,HeightCm,BMI,WaistCm,BodyFatPercent,Goal"};foreach(var r in records)rows.Add(string.Join(",",new[]{Csv(r.RecordedAt.ToString("yyyy-MM-dd")),r.WeightKg.ToString(CultureInfo.InvariantCulture),r.HeightCm.ToString(CultureInfo.InvariantCulture),r.Bmi.ToString(CultureInfo.InvariantCulture),r.WaistCm.ToString(CultureInfo.InvariantCulture),r.BodyFatPercent.ToString(CultureInfo.InvariantCulture),Csv(r.Goal)}));try{File.WriteAllLines(dialog.FileName,rows,new UTF8Encoding(true));MessageBox.Show(fa?"فایل ذخیره شد":"CSV exported");}catch(Exception ex){MessageBox.Show(ex.Message);}}}
 }
}
